diff --git a/.github/workflows/ci.yml b/.github/workflows/ci.yml
index 665b511614..ae7fbd6593 100644
--- a/.github/workflows/ci.yml
+++ b/.github/workflows/ci.yml
@@ -1003,10 +1003,11 @@ jobs:
           # to a spawning test VM dies mid-handshake ("Failed to load …:
           # Connection closed before full header was received / Connection
           # reset by peer") — an arbitrary victim file, 6/6 occurrences on
-          # this leg family. The wrapper re-runs ONLY that dropped file once
-          # (gh-1026 rerun-only-failed discipline); real failures carry no
-          # ws-drop signature and stay loud. junit below still reads the
-          # attempt-1 main log — a healed rerun writes to …retry.json.
+          # this leg family. The wrapper re-runs ONLY the failed inventory
+          # (gh-1026 rerun-only-failed discipline), bounded ≤2 reruns with a
+          # drain backoff; real failures carry no ws-drop signature and stay
+          # loud. junit below still reads the attempt-1 main log — a healed
+          # rerun writes to …retry.json.rerunK.
           bash scripts/load_drop_retry.sh \
             "build/test-results/dart-shard-${{ matrix.shard }}.json" \
             "build/test-results/dart-shard-${{ matrix.shard }}.retry.json" \
@@ -1453,8 +1454,9 @@ jobs:
           mkdir -p build/test-results
           # Issue #2331: same loopback-ws loader-drop family as the core
           # shards (occ1 + occ5 hit THIS leg at --concurrency=4 — the cap
-          # alone does not kill the class). One-shot rerun of the dropped
-          # file only; see scripts/load_drop_retry.sh.
+          # alone does not kill the class). Rerun of the failed inventory
+          # only — bounded (≤2) with drain backoff; see
+          # scripts/load_drop_retry.sh.
           bash scripts/load_drop_retry.sh \
             "build/test-results/integration-shard-${{ matrix.shard }}.json" \
             "build/test-results/integration-shard-${{ matrix.shard }}.retry.json" \
diff --git a/test/ci_load_drop_retry_guard_test.dart b/test/ci_load_drop_retry_guard_test.dart
index 15df50fc7c..7afa195f87 100644
--- a/test/ci_load_drop_retry_guard_test.dart
+++ b/test/ci_load_drop_retry_guard_test.dart
@@ -2,16 +2,17 @@
 // Use of this source code is governed by a MIT license that can be found
 // in the LICENSE file.

-/// Issue #2331 — the sharded dart test legs ride the one-shot loopback-ws
+/// Issue #2331 — the sharded dart test legs ride the bounded loopback-ws
 /// load-drop retry (`scripts/load_drop_retry.sh`).
 ///
 /// Family: under CI-leg load the dart test loader's loopback WebSocket to a
 /// freshly spawned test VM dies mid-handshake (`Failed to load "x_test.dart": Connection closed before full header was received` or
-/// `Connection reset by peer, uri=http://127.0.0.1:…/ws`). Six occurrences (issue card), all in
+/// `Connection reset by peer, uri=http://127.0.0.1:…/ws`). Ten occurrences (issue card), all in
 /// the `test-core` (×4) and `pty-integration-linux` (×3) shards on
 /// ubuntu-24.04-arm; the victim file is arbitrary, every test that ran was
-/// green. The wrapper re-runs ONLY the dropped file(s) once (the gh-1026
-/// rerun-only-failed discipline); a concurrency cap was rejected: the PTY
+/// green. The wrapper re-runs ONLY the failed inventory — bounded (≤2
+/// reruns, drain backoff; the gh-1026 rerun-only-failed discipline); a
+/// concurrency cap was rejected: the PTY
 /// leg dropped twice AT its explicit `--concurrency=4`, and lowering it
 /// collides with the gh-1300 shard-duration budgets (420 s/shard, down-only
 /// ratchet).
diff --git a/test/scripts/load_drop_retry_test.dart b/test/scripts/load_drop_retry_test.dart
index 7cf38c0e98..c5f07f123f 100644
--- a/test/scripts/load_drop_retry_test.dart
+++ b/test/scripts/load_drop_retry_test.dart
@@ -2,23 +2,30 @@
 // Use of this source code is governed by a MIT license that can be found
 // in the LICENSE file.

-/// Issue #2331: `scripts/load_drop_retry.sh` — the one-shot loopback-ws
+/// Issue #2331: `scripts/load_drop_retry.sh` — the bounded loopback-ws
 /// load-drop retry behind the sharded dart test legs.
 ///
 /// Under CI-leg load the dart test loader's loopback WebSocket to a freshly
 /// spawned test VM dies mid-handshake (`Failed to load "x_test.dart": Connection closed before full header was received` /
 /// `Connection reset by peer, uri=http://127.0.0.1:…/ws`). The victim file is arbitrary, never an
-/// assertion failure (6/6 occurrences). The wrapper must:
+/// assertion failure (10/10 occurrences on the card). The wrapper must:
 ///   - rerun at all ONLY on that signature (no signature → no rerun, loud);
-///   - rerun the FULL attempt-1 failed inventory ONCE — the ws-dropped
-///     files PLUS every failed suite the attempt-1 reporter log records
-///     (`gate_failed_targets.py`) — so a healed rerun can never mask a
-///     co-occurring real failure (PR #2347 review round 1, blocking):
-///     assertion failure + drop → the rerun includes the failing suite and
-///     the shard stays red;
