  drop-closed-header)
    echo '$droppedClosedHeader'
    exit 1 ;;
  drop-conn-reset)
    echo '$droppedConnReset'
    exit 1 ;;
  drop-always)
    echo '$droppedClosedHeader'
    exit 1 ;;
  assert-fail)
    echo '[E] Expected: true'
    echo '  Actual: false'
    exit 1 ;;
  ws-no-path)
    echo 'socket error: Connection reset by peer'
    exit 1 ;;
  drop-two-plus-compile-error)
